function descriptor()return{title='Extension API Contract',version='1.1',capabilities={'input-listener','playing-listener','meta-listener','menu'}}end
local d
local function test(name,fn)local ok,err=pcall(fn);d:add_label((ok and 'PASS ' or 'FAIL ')..name..(ok and '' or ': '..tostring(err)),1,#_vela_model.widgets+1,4,1)end
function activate()
 d=vlc.dialog('API Contract')
 test('upstream function inventory',function()local surfaces={["config"]={"get","set","datadir","userdatadir","homedir","configdir","cachedir","datadir_list"},["input"]={"is_playing","item","add_subtitle","add_subtitle_mrl"},["object"]={"input","playlist","libvlc","find","vout","aout"},["strings"]={"decode_uri","encode_uri_component","make_uri","make_path","url_parse","resolve_xml_special_chars","convert_xml_special_chars","from_charset"},["var"]={"inherit","get","get_list","set","create","trigger_callback","libvlc_command","inc_integer","dec_integer","count_choices","toggle_bool"},["net"]={"listen_tcp","connect_tcp","close","send","recv","poll","read","write","url_parse","stat","opendir"},["io"]={"mkdir","open","readdir","unlink"},["volume"]={"get","set","up","down"},["video"]={"fullscreen"},["osd"]={"icon","message","slider","channel_register","channel_clear"},["playlist"]={"prev","next","skip","play","pause","stop","clear","repeat","repeat_","loop","random","goto","gotoitem","add","enqueue","get","search","current","sort","status","delete","move"},["sd"]={"get_services_names","add","remove","is_loaded"},["msg"]={"dbg","info","warn","err"}};for family,names in pairs(surfaces)do for _,name in ipairs(names)do assert(type(vlc[family][name])=='function',family..'.'..name)end end end)
 test('native config',function()local v=vlc.config.get('network-caching');assert(type(v)=='number');vlc.config.set('network-caching',1234);assert(vlc.config.get('network-caching')==1234);vlc.config.set('network-caching',v);assert(type(vlc.config.datadir_list('modules'))=='table')end)
 test('native variables',function()local o=vlc.object.libvlc();vlc.var.create(o,'vela-contract-number',12);assert(vlc.var.get(o,'vela-contract-number')==12);vlc.var.create(o,'vela-contract-bool',false);assert(vlc.var.toggle_bool(o,'vela-contract-bool'));vlc.var.create(o,'vela-contract-string','initial');vlc.var.set(o,'vela-contract-string','edited');assert(vlc.var.get(o,'vela-contract-string')=='edited');local i=vlc.object.input();local old=vlc.var.get(i,'audio-delay');vlc.var.set(i,'audio-delay',12);assert(vlc.var.inc_integer(i,'audio-delay')==13);assert(vlc.var.dec_integer(i,'audio-delay')==12);vlc.var.set(i,'audio-delay',old);assert(type(vlc.var.count_choices(i,'audio-es'))=='number');assert(type(vlc.var.get_list(i,'audio-es'))=='table');local rate=vlc.var.get(i,'rate');vlc.var.set(i,'rate',1.25);assert(vlc.var.get(i,'rate')==1.25);vlc.var.set(i,'rate',rate);local aout=vlc.object.aout();local mute=vlc.var.get(aout,'mute');vlc.var.set(aout,'mute',not mute);assert(vlc.var.get(aout,'mute')==not mute);vlc.var.set(aout,'mute',mute)end)
 test('native input and objects',function()local i=vlc.input.item();assert(i and i:uri()~='' and i:name()~='');assert(type(i:duration())=='number');assert(type(i:stats())=='table');assert(type(i:info())=='table');i:set_meta('description','Vela contract');assert(i:metas().description=='Vela contract');assert(type(i:is_preparsed())=='boolean');assert(vlc.object.aout());assert(vlc.object.vout());assert(vlc.object.find()==nil);assert(vlc.input.is_playing())end)
 test('cancellable command status',function()assert(os.execute('exit 7')==1792);assert(os.execute()==1)end)
 test('native strings',function()local a,b=vlc.strings.decode_uri('a%20b','c%20d');assert(a=='a b' and b=='c d');assert(vlc.strings.from_charset('ISO-8859-1',string.char(233))=='é');assert(vlc.strings.resolve_xml_special_chars('&lt;x&gt;')=='<x>');assert(vlc.strings.convert_xml_special_chars('<x>')=='&lt;x&gt;');assert(vlc.strings.encode_uri_component('a b')=='a%20b');local p=vlc.strings.url_parse('https://user:pass@example.com:123/a?q=1');assert(p.host=='example.com' and p.port==123);assert(vlc.strings.make_path(vlc.strings.make_uri('/tmp/vela-test'))=='/tmp/vela-test')end)
 test('native memory stream and XML',function()local s=vlc.memory_stream('<root id="7"><child>text</child></root>');assert(s:getsize()>0);assert(s:read(5)=='<root');assert(s:seek(0));local x=vlc.xml():create_reader(s);local kind,name=x:next_node();assert(kind==1 and name=='root');local k,v=x:next_attr();assert(k=='id' and v=='7');assert(x:node_empty()==0);assert(x:next_node()==1)end)
 test('native file IO',function()local name=vlc.config.userdatadir()..'/api-contract.txt';local f=assert(vlc.io.open(name,'w+'));assert(f:write('first\nsecond'));f:flush();f:seek('set',0);assert(f:read('*l')=='first');assert(f:read('*a')=='second');f:close();local stat=vlc.net.stat(name);assert(stat.size==12);assert(type(vlc.io.readdir(vlc.config.userdatadir()))=='table');local s=vlc.stream(vlc.strings.make_uri(name));assert(s:readline()=='first');assert(s:seek(0));assert(s:getsize()==12);assert(vlc.io.unlink(name)==0)end)
 test('native HTTP stream',function()local s=vlc.stream('http://127.0.0.1:18763/embedded.srt');assert(s and s:read(1)=='1');assert(s:getsize()>0);assert(s:seek(0));assert(s:readline()=='1')end)
 test('native network socket and poll',function()local fd=vlc.net.connect_tcp('127.0.0.1',18763);assert(fd>=0);assert(vlc.net.send(fd,'GET /embedded.srt HTTP/1.0\r\nHost: localhost\r\n\r\n')>0);local fds={[fd]=vlc.net.POLLIN};assert(vlc.net.poll(fds)>0);assert(vlc.net.recv(fd,4096):match('200 OK'));vlc.net.close(fd);assert(type(vlc.errno.ENOENT)=='number')end)
 test('native VLM',function()local vm=vlc.vlm();local message,code=vm:execute_command('new vela_contract broadcast enabled');assert(code==0 and type(message)=='table');local _,deleted=vm:execute_command('del vela_contract');assert(deleted==0)end)
 test('native volume units',function()
  local function settle(value)for i=1,50 do if math.abs(vlc.volume.get()-value)<=1 then return end;vlc.misc.mwait(vlc.misc.mdate()+10000)end;error('volume readback '..vlc.volume.get()..' requested '..value..' input state '..tostring(vlc.object.input() and vlc.var.get(vlc.object.input(),'state')))end
  local old=vlc.volume.get();assert(vlc.volume.set(128)==0);settle(128);local raised=vlc.volume.up(1);assert(raised>128,'up '..raised);settle(raised);local lowered=vlc.volume.down(1);assert(lowered<raised,'down '..lowered);settle(lowered);vlc.volume.set(old);settle(old)
 end)
 test('native video fullscreen',function()local v=vlc.object.vout();local old=vlc.var.get(v,'fullscreen');assert(vlc.video.fullscreen('on'));assert(vlc.var.get(v,'fullscreen'));assert(not vlc.video.fullscreen('off'));vlc.video.fullscreen(old and 'on' or 'off')end)
 test('native OSD',function()local c=vlc.osd.channel_register();assert(type(c)=='number');vlc.osd.message('Vela API test',c,'top-right',100000);vlc.osd.icon('play',c);vlc.osd.slider(50,'horizontal',c);vlc.osd.channel_clear(c)end)
 test('playlist CRUD and stable IDs',function()local count=vlc.playlist.enqueue({{path='file:///tmp/vela-contract-b',name='B',duration=3,options={':network-caching=500'},artist='test',meta={custom_tag='custom'}},{path='file:///tmp/vela-contract-a',name='A'}});assert(count==2);local rows=vlc.playlist.get('normal').children;local b,a=rows[#rows-1],rows[#rows];assert(b.item:uri()==b.path and b.item:metas().artist=='test');assert(vlc.playlist.get(b.id).name=='B');b.item:set_meta('description','persistent edit');assert(vlc.playlist.get(b.id).item:metas().description=='persistent edit');assert(b.item:metas().custom_tag=='custom');assert(vlc.playlist.get(vlc.playlist.current()).item:metas().description=='Vela contract');vlc.playlist.sort('title');assert(vlc.playlist.get(b.id).name=='B');assert(vlc.playlist.move(b.id,a.id)==0);assert(vlc.playlist.get(b.id).name=='B');assert(#vlc.playlist.search('vela-contract').children==2);assert(vlc.playlist.delete(a.id)==0);assert(vlc.playlist.get(a.id)==nil);assert(vlc.playlist.delete(b.id)==0);assert(vlc.playlist.current()>0);local obj=vlc.object.playlist();vlc.var.set(obj,'random',true);assert(vlc.var.get(obj,'random'));assert(not vlc.playlist.random(false));assert(vlc.playlist.repeat_(true));assert(vlc.var.get(obj,'repeat'));vlc.playlist.repeat_(false);assert(vlc.playlist.loop(true));vlc.playlist.loop(false)end)
 test('service discovery lifecycle',function()local services=vlc.sd.get_services_names();assert(type(services)=='table');if services.podcast then assert(vlc.sd.add('podcast')==0,'podcast start');assert(vlc.sd.is_loaded('podcast'),'podcast loaded');local obj=vlc.object.playlist();vlc.var.set(obj,'podcast-urls','http://127.0.0.1:18763/podcast.xml');local found=false;local function episode(node)for _,child in ipairs(node.children or {})do if child.path=='http://127.0.0.1:18763/test.mp4' and child.item:uri()==child.path then return true end;if episode(child)then return true end end;return false end;for i=1,50 do local root=vlc.playlist.get('podcast');if root and episode(root)then found=true;break end;vlc.misc.mwait(vlc.misc.mdate()+100000)end;assert(found,'podcast episode tree');local root=vlc.playlist.get('root');assert(#root.children>=3,'root includes discovery');local service=vlc.playlist.get('podcast');assert(vlc.playlist.get(service.id).name==service.name,'service numeric selector');assert(vlc.sd.remove('podcast')==0);assert(not vlc.sd.is_loaded('podcast'))end;assert(not vlc.sd.is_loaded('vela-nonexistent'));assert(vlc.sd.add('vela-nonexistent')~=0);assert(vlc.sd.remove('vela-nonexistent')~=0)end)
 test('dialog spans and spinner',function()local dropdown=d:add_dropdown(1,60);assert(dropdown:get_value()==-1);dropdown:add_value('Zero',0);dropdown:add_value('One',1);local id,label=dropdown:get_value();assert(id==0 and label=='Zero');dropdown:clear();assert(dropdown:get_value()==-1);d:del_widget(dropdown);local spin=d:add_spin_icon(4,1,1,2,32,32);spin:animate();spin:stop();local html=d:add_html('<b>Native HTML</b>',1,40,4,2,300,80);assert(html.span==4 and html.rowspan==2);d:del_widget(spin);d:del_widget(html);d:update()end)
 test('expanded native layout',function()local w=d:add_label('Wide extension',16,120,20,3,3000,2100);d:update();assert(w.col==16 and w.row==120 and w.width==3000);end)
 test('bundled modules',function()local xml=require('simplexml');assert(type(xml)=='table');assert(_VERSION=='Lua 5.1');local compiled=assert(loadfile(os.getenv('VLC_DATA_PATH')..'/lua/modules/common.luac'));assert(type(compiled())=='table')end)
end
function input_changed()if d then d:add_label('EVENT input',1,50,4,1)end end
function playing_changed(status)if d then d:add_label(type(status)=='number' and 'EVENT playing number' or 'EVENT playing missing',1,51,4,1);d:add_label('EVENT state '..tostring(status),1,54,4,1)end end
function meta_changed()if d then d:add_label('EVENT meta',1,52,4,1)end end
function menu()return {[1]='Check rebound engine'}end
function trigger_menu(id)if id==1 then d:add_label(vlc.input.item() and 'REBIND OK' or 'REBIND FAIL',1,53,4,1)end end
function deactivate()if d then d:delete()end end
